WITH matched_keys AS (SELECT country FROM sessions EXCEPT SELECT country FROM sessions WHERE browser = 'Edge'), reconciled AS (SELECT s.* FROM sessions s JOIN matched_keys k ON s.country = k.country) SELECT customer_id, browser, COUNT_IF(device = 'tablet') AS tablet_events, SORT_ARRAY(COLLECT_SET(country)) AS country_list, SORT_ARRAY(COLLECT_SET(browser)) AS browser_list, COUNT_IF(device = 'mobile') AS mobile_events, COUNT(*) AS num_rows, COUNT(DISTINCT customer_id) AS distinct_customer_ids FROM reconciled GROUP BY customer_id, browser;
